# Count how many tasks start on each machine
start_counts = {}
for out in outcomes(doc, "Cell window 26"):
    if out["kind"] == "start":
        mid = out["entities"][1]
        start_counts[mid] = start_counts.get(mid, 0) + 1

print("Start counts per machine:")
for mid, cnt in sorted(start_counts.items()):
    print(f"{mid}: {cnt}")

# Print all machine failure/return events with timestamps
evnode = node_by_title(doc, "Cell window 26: Events")
for idx, line in enumerate(evnode["lines"]):
    if "failed" in line or "returned" in line:
        print(f"Line {idx}: {line}")

# Verify number of tasks left queued at time 1200
waiting_node = node_by_title(doc, "Cell window 26: Queue at window end: Tasks waiting at time 1200, in queue order (each will run its full run time once started)")
waiting_rows = table_rows(waiting_node)
print("\nNumber of tasks waiting at 1200:", len(waiting_rows))
print("\nFirst 5 waiting tasks:")
for idx, row in waiting_rows[:5]:
    print(row)

# Gather machine failure/return events
events_node = node_by_title(doc, "Cell window 26: Events")
failed_machines = {}
for line in events_node["lines"]:
    m = re.search(r"machine (\S+)", line)
    if m:
        mid = m.group(1)
        if "failed" in line:
            failed_machines.setdefault(mid, []).append(("fail", line))
        elif "returned" in line:
            failed_machines.setdefault(mid, []).append(("return", line))

print("Failure/return events per machine:", failed_machines)

# Number of fail outcomes
fail_outcomes = [out for out in outcomes(doc, "Cell window 26") if out["kind"] == "fail"]
print("\nNumber of fail outcomes:", len(fail_outcomes))
print("Fail outcome record:", fail_outcomes)

